let currentLanguage = document.documentElement.lang === "de" ? "de" : "en";

/* Select one matching element from the legal page. */
function selectElement(selector) {
  return document.querySelector(selector);
}

/* Select all matching elements from the legal page. */
function selectAllElements(selector) {
  return Array.from(document.querySelectorAll(selector));
}

/* Return translations for the current legal page language. */
function getTranslations() {
  return legalPageTranslations[currentLanguage] || legalPageTranslations.en;
}

/* Check whether the responsive menu is open. */
function isMobileMenuOpen() {
  return document.body.classList.contains("mobile-menu-open");
}

/* Update the language switch image for its state. */
function updateLanguageSwitchImage(isHovering = false) {
  const image = selectElement(".site-header__lang-switch");
  const imageSet = languageSwitchImages[currentLanguage];
  if (!image || !imageSet) return;
  image.src = isHovering ? imageSet.hover : imageSet.default;
}

/* Set one attribute when the matching element exists. */
function setLegalElementAttribute(selector, attribute, value) {
  const element = selectElement(selector);
  if (element) element.setAttribute(attribute, value);
}

/* Update the responsive menu label for its open state. */
function refreshMobileMenuLabel() {
  const menuButton = selectElement(".site-header__menu-toggle");
  const translations = getTranslations();
  if (!menuButton) return;
  const label = isMobileMenuOpen() ? translations.mobileMenu.close : translations.mobileMenu.open;
  menuButton.setAttribute("aria-label", label);
}

/* Set the responsive menu open or closed state. */
function setMobileMenuState(isOpen) {
  const menuButton = selectElement(".site-header__menu-toggle");
  document.body.classList.toggle("mobile-menu-open", isOpen);
  if (menuButton) menuButton.setAttribute("aria-expanded", String(isOpen));
  refreshMobileMenuLabel();
}

/* Close the responsive menu overlay. */
function closeMobileMenu() {
  setMobileMenuState(false);
}

/* Toggle the responsive menu overlay. */
function toggleMobileMenu() {
  setMobileMenuState(!isMobileMenuOpen());
}

/* Update the language button state and label. */
function applyLegalLanguageButton(translations) {
  const languageButton = selectElement(".site-header__lang-button");
  if (!languageButton) return;
  languageButton.setAttribute("aria-label", translations.header.switchLabel);
  languageButton.setAttribute("aria-pressed", currentLanguage === "de" ? "true" : "false");
}

/* Update header labels for the legal page. */
function applyHeaderTexts(translations) {
  document.documentElement.lang = translations.lang;
  setLegalElementAttribute(".site-header__nav", "aria-label", translations.header.navLabel);
  setLegalElementAttribute('.site-header__link[href="#about"]', "aria-label", translations.header.about);
  setLegalElementAttribute('.site-header__link[href="#skills"]', "aria-label", translations.header.skills);
  setLegalElementAttribute('.site-header__link[href="#projects"]', "aria-label", translations.header.projects);
  setLegalElementAttribute(".site-header__logo", "aria-label", translations.header.logoLabel);
  applyLegalLanguageButton(translations);
  updateLanguageSwitchImage(false);
  refreshMobileMenuLabel();
}

/* Update the two footer meta text nodes. */
function applyFooterMetaTexts(metaTexts) {
  const footerMetaItems = selectAllElements(".site-footer__meta span");
  metaTexts.forEach((text, index) => {
    if (footerMetaItems[index]) footerMetaItems[index].textContent = text;
  });
}

/* Update every footer navigation link text. */
function applyFooterLinkTexts(linkTexts) {
  const footerLinks = selectAllElements(".site-footer__nav a");
  linkTexts.forEach((text, index) => {
    if (footerLinks[index]) footerLinks[index].textContent = text;
  });
}

/* Update footer labels and text for the legal page. */
function applyFooterTexts(translations) {
  setLegalElementAttribute(".site-footer__brand", "aria-label", translations.footer.brandLabel);
  setLegalElementAttribute(".site-footer__nav", "aria-label", translations.footer.navLabel);
  applyFooterMetaTexts(translations.footer.meta);
  applyFooterLinkTexts(translations.footer.links);
}

/* Update the legal notice title and content. */
function applyLegalTexts(translations) {
  const title = selectElement("#legalNoticeTitle");
  const content = selectElement("#legalNoticeContent");
  document.title = `${translations.legal.title} | Florian Narr`;
  if (title) title.textContent = translations.legal.title;
  if (content) content.innerHTML = translations.legal.content;
  setLegalElementAttribute(".legal-page__back", "aria-label", translations.legal.backLabel);
}

/* Apply one language to the full legal page. */
function applyPageLanguage(language) {
  currentLanguage = language;
  const translations = getTranslations();
  applyHeaderTexts(translations);
  applyFooterTexts(translations);
  applyLegalTexts(translations);
}

/* Remove the temporary no-transition state after language updates. */
function removeLanguageSwitchingState() {
  document.body.classList.remove("is-language-switching");
}

/* Prevent responsive menu animation jumps during language updates. */
function markLanguageSwitchingState() {
  document.body.classList.add("is-language-switching");
  window.requestAnimationFrame(removeLanguageSwitchingState);
}

/* Toggle between English and German on the legal page. */
function handleLanguageButtonClick() {
  const nextLanguage = currentLanguage === "de" ? "en" : "de";
  markLanguageSwitchingState();
  applyPageLanguage(nextLanguage);
}

/* Show the hover image for the language switch. */
function showLanguageSwitchHoverImage() {
  updateLanguageSwitchImage(true);
}

/* Show the default image for the language switch. */
function showLanguageSwitchDefaultImage() {
  updateLanguageSwitchImage(false);
}

/* Register language switch events on the legal page. */
function registerLanguageButtonEvents() {
  const button = selectElement(".site-header__lang-button");
  if (!button) return;
  button.addEventListener("click", handleLanguageButtonClick);
  button.addEventListener("mouseenter", showLanguageSwitchHoverImage);
  button.addEventListener("mouseleave", showLanguageSwitchDefaultImage);
  button.addEventListener("focus", showLanguageSwitchHoverImage);
  button.addEventListener("blur", showLanguageSwitchDefaultImage);
}

/* Check if a click happened outside the responsive menu. */
function isMobileMenuOutsideClick(event, mobileMenu, menuButton) {
  if (!isMobileMenuOpen()) return false;
  if (!(event.target instanceof Element)) return false;
  const clickedInsideMenu = mobileMenu.contains(event.target);
  const clickedMenuButton = menuButton.contains(event.target);
  return !clickedInsideMenu && !clickedMenuButton;
}

/* Close the responsive menu after a menu link click. */
function registerMobileMenuLinks(mobileMenu) {
  mobileMenu.querySelectorAll("a").forEach((link) => {
    link.addEventListener("click", closeMobileMenu);
  });
}

/* Close the responsive menu when desktop layout returns. */
function handleMobileMenuResize() {
  if (window.innerWidth > 768) closeMobileMenu();
}

/* Close the responsive menu when Escape is pressed. */
function handleMobileMenuKeydown(event) {
  if (event.key === "Escape") closeMobileMenu();
}

/* Close the responsive menu when clicking outside. */
function handleMobileMenuOutsideClick(event, mobileMenu, menuButton) {
  if (isMobileMenuOutsideClick(event, mobileMenu, menuButton)) closeMobileMenu();
}

/* Register global responsive menu events on the legal page. */
function registerMobileMenuGlobalEvents(mobileMenu, menuButton) {
  window.addEventListener("resize", handleMobileMenuResize);
  document.addEventListener("keydown", handleMobileMenuKeydown);
  document.addEventListener("click", (event) => handleMobileMenuOutsideClick(event, mobileMenu, menuButton));
}

/* Register responsive menu events on the legal page. */
function registerMobileMenuEvents() {
  const menuButton = selectElement(".site-header__menu-toggle");
  const mobileMenu = selectElement("#siteHeaderMobileMenu");
  if (!menuButton || !mobileMenu) return;
  menuButton.addEventListener("click", toggleMobileMenu);
  registerMobileMenuLinks(mobileMenu);
  registerMobileMenuGlobalEvents(mobileMenu, menuButton);
}

/* Return the local page target for one hash link. */
function getLocalHashTarget(link) {
  const hash = link.getAttribute("href");
  if (!hash || hash.length <= 1) return null;
  return hash;
}

/* Redirect missing hash targets back to the homepage. */
function handleMissingHashLinkClick(event) {
  const link = event.target.closest('a[href^="#"]');
  if (!link) return;
  const hash = getLocalHashTarget(link);
  if (!hash || document.querySelector(hash)) return;
  event.preventDefault();
  window.location.href = `/index.html${hash}`;
}

/* Register hash redirect handling for legal page nav links. */
function redirectHashLinksToIndex() {
  document.addEventListener("click", handleMissingHashLinkClick);
}

/* Prepare all legal page interactions. */
function initializeLegalPage() {
  applyPageLanguage(currentLanguage);
  registerLanguageButtonEvents();
  registerMobileMenuEvents();
  redirectHashLinksToIndex();
}

initializeLegalPage();